import math

def maxPairStrengthGCD(nums: list[int]) -> int:
    n = len(nums)
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            g = math.gcd(nums[i], nums[j])
            best = max(best, g * (nums[i] + nums[j]))
    return best

#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    long long maxPairStrengthGCD(std::vector<int>& nums) {
        int n = nums.size();
        long long best = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                long long g = std::gcd(nums[i], nums[j]);
                best = std::max(best, g * (nums[i] + nums[j]));
            }
        }
        return best;
    }
};

class Solution {
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    public long maxPairStrengthGCD(int[] nums) {
        int n = nums.length;
        long best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long g = gcd(nums[i], nums[j]);
                best = Math.max(best, g * (nums[i] + nums[j]));
            }
        }
        return best;
    }
}

function gcd(a, b) {
    while (b !== 0) {
        let t = b;
        b = a % b;
        a = t;
    }
    return a;
}

